66	function ensureDirs(): string {
67	  const { adapterPluginsDir } = adapterPluginPaths();
68	  fs.mkdirSync(adapterPluginsDir, { recursive: true });
69	  const pkgJsonPath = path.join(adapterPluginsDir, "package.json");
70	  if (!fs.existsSync(pkgJsonPath)) {
71	    fs.writeFileSync(pkgJsonPath, JSON.stringify({
72	      name: "paperclip-adapter-plugins",
73	      version: "0.0.0",
74	      private: true,
75	      description: "Managed directory for Paperclip external adapter plugins. Do not edit manually.",
76	    }, null, 2) + "\n");
77	  }
78	  return adapterPluginsDir;
79	}
80	
81	function readStore(): AdapterPluginRecord[] {
82	  const { adapterPluginsStorePath } = adapterPluginPaths();
83	  if (storeCache?.path === adapterPluginsStorePath) return storeCache.records;
84	  try {
85	    const raw = fs.readFileSync(adapterPluginsStorePath, "utf-8");
86	    const parsed = JSON.parse(raw);
87	    storeCache = {
88	      path: adapterPluginsStorePath,
89	      records: Array.isArray(parsed) ? (parsed as AdapterPluginRecord[]) : [],
90	    };
91	  } catch {
92	    storeCache = { path: adapterPluginsStorePath, records: [] };
93	  }
94	  return storeCache.records;
95	}
96	
97	function writeStore(records: AdapterPluginRecord[]): void {
98	  ensureDirs();
99	  const { adapterPluginsStorePath } = adapterPluginPaths();
100	  fs.writeFileSync(adapterPluginsStorePath, JSON.stringify(records, null, 2), "utf-8");
101	  storeCache = { path: adapterPluginsStorePath, records };
102	}
